    int numTransactions = transactionsForCoin.length;
    double averageProfit = totalProfit / numTransactions;

    if (averageProfit > maxAverageProfit) {
      maxAverageProfit = averageProfit;
      topCoins = [coinName];
    } else if (averageProfit == maxAverageProfit && transactionsForCoin.length < 3) {
      topCoins

