            "suv": {"name": "SUV", "heightRange": "6'2\" - 6'4\"", "length": "22 - 24 feet"},
            "truck": {"name": "Truck", "heightRange": "6'5\" - 6'7\"", "length": "24 - 26 feet"},
            "van": {"name": "Van", "heightRange": "6'8\" and up", "length": "26+ feet"}
        }
    }')

    for size, info in car_sizes["carSizes"].items():
        if height >= info["heightRange"]:
            return size

    return None

# Test the function
height = 5.5
print("Recommended car size:", get_car_size(height))  # Output: Midsize
```

