Here's a JavaScript function that takes a sentence as input and returns the same sentence with the order of adjectives switched:

```javascript
function switchAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];
  let currentWord = "";

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(/^[a-zA-Z]+$/)) { // Check if the word is an adjective
      adjectives.push(words[i]);
    } else {
      currentWord += ` ${words[i]}`;
    }
  }

  return `${currentWord} ${adjectives.join(" ")}`;
}

const sentence = "Beautiful green trees are in the park";
const result = switchAdjectives(sentence);
console.log(result); // Output: "Green beautiful trees are in the park"
```

