Here's a C++ program that generates the Fibonacci sequence using a recursive function. It prompts the user to input the first two integers and the number of sequence elements to generate, and outputs the generated sequence. It also includes error handling for invalid inputs.

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    int num1, num2, num3;
    string input;
    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);
    if (!(iss >> num1 >> num2)) {
        throw runtime_error("Invalid input");
    }
    cout << "Enter the number of sequence elements to generate: ";
    cin >> num3;
    if (num3 <= 0) {
        throw runtime_error("Invalid input");
    }
    try {
        int sequence[num3];
        sequence[0] = num1;
        sequence[1] = num2;
        for (int i = 2; i < num3; i++) {
            sequence[i] = fibonacci(i, num1, num2);
        }
        cout << "Fibonacci sequence: ";
        for (int i = 0; i < num3; i++) {
            cout << sequence[i] << ", ";
        }
        cout << endl;
    } catch (runtime_error& e) {
        cerr << "Error: " << e.what() << endl;
    }
    return 0;
}
```

