            $product_tax_class = $item->get_tax_class();
            if (!empty($product_tax_class)) {
                $formatted_order[] = "$product_name, $product_tax_class";
            } else {
                $formatted_order[] = $product_name;
            }
        }
        $formatted_orders[] = implode(', ', $formatted_order);
    }
    return $formatted_orders;
}

