        tense = 'conditional';
    elseif contains(words, {'been', 'gone', 'come', 'done'})
        tense = 'perfect';
    elseif contains(words, {'going', 'coming', 'being'})
        tense = 'present_continuous';
    elseif contains(words, {'have', 'has', 'had'})
        tense = 'simple_past';
    elseif contains(words, {'is', 'are', 'was', 'were'})
        tense = 'simple_present';
    else
        tense = 'unknown';
    end
end

