function determineProtocol(inputData) {
  if (inputData.protocol === 'ipv6') {
    return 'IPv6';
  } else if (inputData.protocol === 'http') {
    return 'HTTP';
  } else if (inputData.protocol === 'udp') {
    return 'UDP';
  } else {
    return 'Unknown';
  }
}

