function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A1:C10"); // Assuming your data range is A1 to C10
  var placeName = "New York"; // Replace with the place name you want to search for

  var geocoder = new google.maps.Geocoder();

  for (var i = 1; i <= dataRange.getNumRows(); i++) {
    var address = dataRange.getCell(i, 1).getValue();

    if (address === placeName) {
      geocoder.geocode({ 'address': address }, function(results, status) {
        if (status === 'OK') {
          var latitude = results[0].geometry.location.lat();
          var longitude = results[0].geometry.location.lng();

          dataRange.getCell(i, 2).setValue(latitude);
          dataRange.getCell(i, 3).setValue(longitude);
        }
      });
    }
  }
}
```

Replace `"New York"` with the place name you want to search for, and adjust the data range as needed. This script will loop through the specified data range, search for the given place name, and store the latitude and longitude in the corresponding columns.

