		return
	}

	re := regexp.MustCompile(`type (\w+)\{`)
	matches := re.FindStringSubmatch(string(content))

	if len(matches) != 2 {
		fmt.Println("Unable to find struct definition in file")
		return
	}

	structDef := matches[1]

	fields := extractFields(structDef)

	avroSchema := generateAvroSchema(fields)

	err = ioutil.WriteFile("struct.avsc", []byte(avroSchema), 0644)
	if err != nil {
		fmt.Println("Error writing file:", err)
		return
	}

	fmt.Printf("Generated Avro schema for %s:\n%s\n", structName, avroSchema)
}

func extractFields(structDef string) []string {
	fields := []string{}

	re := regexp.MustCompile(`(\w+): (\w+);`)
	matches := re.FindAllString(structDef, -1)

	for _, match := range matches {
		fieldName := strings.SplitN(match, ": ", 2)[0]
		fieldType := strings.SplitN(match, ": ", 2)[1]

		fields = append(fields, fmt.Sprintf("%s: %s", fieldName, fieldType))
	}

	return fields
}

