Here's the new array with the positions adjusted based on the randomize value:

```javascript
const fruits = [
  { name: 'apple', position: 1, randomize: false },
  { name: 'pineapple', position: 2, randomize: false },
  { name: 'orange', position: 3, randomize: true },
  { name: 'banana', position: 4, randomize: true },
  { name: 'grapes', position: 8, randomize: false },
  { name: 'lemon', position: 11, randomize: true },
  { name: 'jack fruit', position: 10, randomize: false },
  { name: 'dragon fruit', position: 5, randomize: false },
  { name: 'green apple', position: 9, randomize: false }
];

const newArray = [];

fruits.forEach(fruit => {
  if (fruit.randomize) {
    const randomIndex = Math.floor(Math.random() * 11);
    newArray.splice(randomIndex, 0, fruit);
  } else {
    newArray.push(fruit);
  }
});

console.log(newArray);
```

This code will output the following array:

```
[
  'apple',
  'pineapple',
  'banana',
  'grapes',
  'lemon',
  'jack fruit',
  'dragon fruit',
  'green apple',
  'orange'
]
```

As you can see, the positions of the items have been adjusted according to their `randomize` values. The items with `randomize` set to `true` have been inserted at random positions in the array, while the items with `randomize` set to `false` have been added to the end of the array in the order they appear in the input array.

To retrieve the username from the JWT token in ASP.NET C# WebAPI, you can follow these steps:

1. Install the `Microsoft.IdentityModel.Tokens` package if you haven't already. You can do this by running the following command in the Package Manager Console:
```
Install-Package Microsoft.IdentityModel.Tokens
```

2. In your WebApi project, create a new class that will handle the token validation and username extraction. For example:
```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.IdentityModel.Tokens;

public class JwtTokenHandler
{
    private readonly string _secretKey;

    public JwtTokenHandler(string secretKey)
    {
        _secretKey = secretKey;
    }

    public ClaimsPrincipal ValidateToken(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var key = Encoding.ASCII.Parse(_secretKey);
        var tokenDescriptor = new SecurityTokenDescriptor
        {
            TokenType = "JWT",
            Issue = new DateTime(2020, 1, 1),
            Expiration = new DateTime(2020, 1, 2),
            SigningCredentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256Signature)
        };

        var tokenValidationParameters = new TokenValidationParameters
        {
            ValidIssuer = "your_issuer",
            ValidAudience = "your_audience",
            IssuerSigningKey = key,
            ValidateIssuerSigningKey = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuer = true,
            ValidateActor = true
        };

        var securityToken = tokenHandler.ReadJwtToken(token, tokenValidationParameters);
        return new ClaimsPrincipal(securityToken.Claims);
    }

    public string GetUsername(ClaimsPrincipal principal)
    {
        return principal?.FindFirst("username")?.Value;
    }
}
```
