```matlab
% Define the population size, number of generations, and fitness function
populationSize = 100;
numGenerations = 100;
fitnessFunction = @(x) x(1) * x(2); % Fitness is proportional to the first two genes

% Initialize the population with random individuals
population = randi([0, 1], populationSize, 2);

% Evaluate the fitness of each individual
fitness = fitnessFunction(population);

% Select the parents for the next generation based on their fitness
parents = sort(fitness, 'descend');
parentCounts = zeros(size(parents), 1);
for i = 1:length(parents)
    parentCounts(i) = min(populationSize - i + 1, floor(parents(i) / sum(fitness)));
end

% Create the next generation by combining the selected parents
nextGeneration = zeros(populationSize, 2);
for i = 1:length(parents)
    for j = 1:parentCounts(i)
        nextGeneration(i, :) = population(parents(i), :);
    end
end

% Evaluate the fitness of the next generation
nextFitness = fitnessFunction(nextGeneration);

% Print the results
fprintf('Generation: %d\n', numGenerations);
fprintf('Average Fitness: %.2f\n', mean(fitness));
fprintf('Next Generation Average Fitness: %.2f\n', mean(nextFitness));
```

