To create a simple toast notification using React Context, follow these steps:

1. First, let's create a ToastContext.js file to manage the toast notifications.

```javascript
import { createContext, useState } from 'react';

const ToastContext = createContext({
  showToast: () => {},
});

export function ToastProvider({ children }) {
  const [toastMessage, setToastMessage] = useState(null);

  const showToast = (message) => {
    setToastMessage(message);
    setTimeout(() => {
      setToastMessage(null);
    }, 3000);
  };

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export default ToastContext;
```

2. Now, let's create a Toast.js file to display the toast notification.

```javascript
import React from 'react';
import { useContext } from 'react';

function Toast() {
  const { toastMessage } = useContext(ToastContext);

  if (!toastMessage) {
    return null;
  }

  return (
    <div className="toast">
      <p>{toastMessage}</p>
    </div>
  );
}

export default Toast;
```

3. Finally, you can use the ToastProvider and Toast components in your main application component.

```javascript
import React from 'react';
import ToastProvider from './ToastContext';
import Toast from './Toast';

function App() {
  return (
    <ToastProvider>
      <div>
        <button onClick={() => ToastContext.showToast('Hello, world!')}>Show Toast</button>
        <Toast />
      </div>
    </ToastProvider>
  );
}

export default App;
```

Now you have a simple toast notification system using React Context. You can customize the toast message, style, and behavior as needed.

