Sure! Here are four methods to open/close the camera and microphone using JavaScript:

Method 1: Using the MediaStream API

```javascript
function openCamera() {
  navigator.mediaDevices.getUserMedia({ video: true })
    .then(stream => {
      // Camera opened successfully
      console.log('Camera opened');
    })
    .catch(error => {
      // Error opening camera
      console.error('Error opening camera:', error);
    });
}

function closeCamera() {
  const stream = navigator.mediaDevices.getUserMedia();
  if (stream) {
    stream.getTracks().forEach(track => track.stop());
    console.log('Camera closed');
  } else {
    console.log('No camera open');
  }
}

function openMicrophone() {
  navigator.mediaDevices.getUserMedia({ audio: true })
    .then(stream => {
      // Microphone opened successfully
      console.log('Microphone opened');
    })
    .catch(error => {
      // Error opening microphone
      console.error('Error opening microphone:', error);
    });
}

function closeMicrophone() {
  const stream = navigator.mediaDevices.getUserMedia();
  if (stream) {
    stream.getTracks().forEach(track => track.stop());
    console.log('Microphone closed');
  } else {
    console.log('No microphone open');
  }
}
```

Method 2: Using the getUserMedia function

```javascript
function openCamera() {
  getUserMedia({ video: true }, stream => {
    // Camera opened successfully
    console.log('Camera opened');
  }, error => {
    // Error opening camera
    console.error('Error opening camera:', error);
  });
}

function closeCamera() {
  getUserMedia({ video: false }, stream => {
    // Camera closed successfully
    console.log('Camera closed');
  }, error => {
    // Error closing camera
    console.error('Error closing camera:', error);
  });
}

