  filename: 'your_image_filename.jpg',
  contentType: 'image/jpeg',
});

fileStream.pipe(writeStream);

// Once the file is written to MongoDB, you can retrieve it using the following code:
const getImage = async () => {
  const image = await Image.findOne();
  const readStream = gfs.createReadStream({ _id: image._id });
  return readStream;
};

getImage()
