Here's the `redis.js` file inside the `utils` folder with the requested class:

```javascript
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.redis = new Redis();

    this.redis.on('error', (err) => {
      console.error('Error occurred while connecting to Redis:', err);
    });
  }

  async isAlive() {
    try {
      await this.redis.ping();
      return true;
    } catch (error) {
      console.error('Error while checking Redis connection:', error);
      return false;
    }
  }

  async get(key) {
    try {
      const value = await this.redis.get(key);
      return value;
    } catch (error) {
      console.error('Error while getting value from Redis:', error);
      throw error;
    }
  }

  async set(key, value, duration) {
    try {
      await this.redis.set(key, value, 'EX', duration);
      return true;
    } catch (error) {
      console.error('Error while setting value in Redis:', error);
      throw error;
    }
  }

  async del(key) {
    try {
      await this.redis.del(key);
      return true;
    } catch (error) {
      console.error('Error while deleting value from Redis:', error);
      throw error;
    }
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

